-- Function: public.fn_get_intelligence_data_quality
-- Backup generated on 2026-10-25 20:33:25

CREATE OR REPLACE FUNCTION public.fn_get_intelligence_data_quality(p_tenant_id uuid, p_org_id uuid, p_branch_id uuid, p_classroom_id uuid, p_start_date date, p_end_date date)  RETURNS TABLE(missing_departure_times_count integer, drafts_awaiting_review_count integer)  LANGUAGE sql  STABLE AS $function$     SELECT          (SELECT COUNT(*)::int           FROM child_attendance ca          JOIN classrooms cl ON ca.classroom_id = cl.id          JOIN branches b ON cl.branch_id = b.id          WHERE ca.tenant_id = p_tenant_id            AND b.organization_id = p_org_id            AND (p_branch_id IS NULL OR b.id = p_branch_id)            AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)            AND ca.status = 'Present'            AND ca.departure_time IS NULL            AND ca.attendance_date < CURRENT_DATE            AND ca.attendance_date BETWEEN p_start_date AND p_end_date) AS missing_departure_times_count,         (SELECT COUNT(*)::int           FROM parent_communications pc          JOIN classrooms cl ON pc.classroom_id = cl.id          JOIN branches b ON cl.branch_id = b.id          WHERE pc.tenant_id = p_tenant_id            AND b.organization_id = p_org_id            AND (p_branch_id IS NULL OR b.id = p_branch_id)            AND (p_classroom_id IS NULL OR cl.id = p_classroom_id)            AND pc.status IN ('Draft', 'PendingReview')) AS drafts_awaiting_review_count; $function$ ;
